/* Token Radar's dark console theme. One palette, two radii, two families; everything else is
   spacing, a hairline and a type step. No network, no images: every pixel is CSS. */
:root {
  --canvas: #0e1210;
  --surface: #161c19;
  --surface-2: #1c2420;
  --ink: #e8ede9;
  --muted: #9aa8a0;
  --faint: #6b7a72;
  --border: #2a352f;
  --accent: #e8a33d;
  --accent-soft: rgba(232, 163, 61, 0.14);
  --good: #5ec98a;
  --bad: #e06c5b;
  --radius-control: 8px;
  --radius-panel: 14px;
  --font-body: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-num: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 24px;
  --s6: 32px;
  --s7: 48px;
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font: 400 15px/1.55 var(--font-body);
  text-wrap: pretty;
}
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; text-wrap: balance; }
h1 { font-size: 32px; line-height: 1.12; font-weight: 650; }
h2 { font-size: 20px; line-height: 1.2; font-weight: 650; }
h3 { font-size: 15px; line-height: 1.25; font-weight: 650; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--accent); }
.skip {
  position: absolute; left: -9999px; top: 0; padding: var(--s2) var(--s4);
  background: var(--surface); border: 1px solid var(--border); z-index: 20;
}
.skip:focus { left: var(--s4); top: var(--s4); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.shell { max-width: 1320px; margin: 0 auto; padding: var(--s5) var(--s6) var(--s7); }
.top {
  display: flex; align-items: flex-start; justify-content: space-between; gap: var(--s5);
  padding-bottom: var(--s4); border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: center; gap: var(--s3); }
.mark {
  width: 34px; height: 34px; border-radius: 50%; flex: none;
  border: 2px solid var(--accent);
  background: radial-gradient(circle at 50% 50%, var(--accent) 0 3px, transparent 4px),
    conic-gradient(from 210deg, transparent 0 300deg, var(--accent) 300deg 360deg);
}
.brand-name { font-family: var(--font-num); font-size: 13px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted); }
.brand-name b { color: var(--ink); font-weight: 650; }
.top-meta { display: flex; flex-wrap: wrap; gap: var(--s2) var(--s4); justify-content: flex-end; color: var(--muted); font-size: 13px; }
.top-meta span { white-space: nowrap; }
.top-meta b { color: var(--ink); font-weight: 550; }

.lede { display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(300px, 0.65fr); gap: var(--s6); padding: var(--s6) 0 var(--s5); }
.lede p { color: var(--muted); max-width: 64ch; margin-top: var(--s2); }
.lede p b { color: var(--ink); font-weight: 600; }
.honest { margin-top: var(--s3); padding: var(--s3) var(--s4); border: 1px solid var(--border); border-left: 3px solid var(--accent); border-radius: var(--radius-control); background: var(--surface); color: var(--muted); font-size: 13px; }
.honest b { color: var(--accent); font-weight: 600; }
.facts { display: grid; gap: var(--s2); align-content: start; border-left: 1px solid var(--border); padding-left: var(--s5); }
.fact { display: flex; align-items: baseline; justify-content: space-between; gap: var(--s3); }
.fact b { font-family: var(--font-num); font-size: 15px; font-weight: 550; }
.fact span { color: var(--muted); font-size: 13px; }

.controls { display: flex; flex-wrap: wrap; align-items: end; gap: var(--s3); padding: var(--s4) 0; border-top: 1px solid var(--border); }
.field { display: grid; gap: var(--s1); }
.field label { color: var(--muted); font-size: 12px; }
.field input, .field select {
  min-height: 38px; padding: 0 var(--s3); border: 1px solid var(--border); border-radius: var(--radius-control);
  background: var(--surface-2); min-width: 160px; color: var(--ink);
}
.field input { min-width: 260px; }
.field select option { background: var(--surface-2); }
.tabs { display: flex; gap: var(--s1); padding: 3px; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); }
.tabs button { min-height: 32px; padding: 0 var(--s3); border: 0; border-radius: 6px; background: transparent; color: var(--muted); }
.tabs button[aria-pressed="true"] { background: var(--accent); color: #171207; font-weight: 600; }
.count { margin-left: auto; color: var(--muted); font-size: 13px; align-self: center; }

.panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-panel); overflow: hidden; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
th, td { padding: var(--s3); border-bottom: 1px solid var(--border); text-align: left; vertical-align: middle; }
th { color: var(--muted); font-size: 12px; font-weight: 550; white-space: nowrap; }
th button { display: inline-flex; align-items: center; gap: var(--s1); border: 0; background: none; padding: 0; color: inherit; font: inherit; }
th button:hover { color: var(--ink); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--surface-2); }
tbody tr[data-selected="true"] { background: var(--accent-soft); }
tr.top3 td:first-child { color: var(--accent); font-weight: 650; }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }
.name { display: grid; gap: 2px; }
.name b { font-weight: 600; }
.sub { color: var(--muted); font-size: 12px; }
.pos { color: var(--good); }
.neg { color: var(--bad); }
.bar { width: 120px; height: 6px; border-radius: 3px; background: var(--border); overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--accent); }
.implied { display: flex; align-items: center; gap: var(--s2); }
.badge { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); font-size: 12px; white-space: nowrap; }
.badge::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--accent); }
.badge.live::before { background: var(--good); }
.watch { color: var(--accent); font-size: 11px; font-family: var(--font-num); letter-spacing: 0.06em; text-transform: uppercase; }

.model { margin-top: var(--s4); padding: var(--s5); display: grid; gap: var(--s3); }
.model h2 { color: var(--ink); }
.formula { font-family: var(--font-num); font-size: 13px; line-height: 1.8; color: var(--muted); overflow-wrap: anywhere; background: var(--canvas); border: 1px solid var(--border); border-radius: var(--radius-control); padding: var(--s3) var(--s4); }
.formula b { color: var(--accent); font-weight: 600; }
.method { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: var(--s4); }
.method h3 { margin-bottom: var(--s1); color: var(--ink); }
.method p { color: var(--muted); font-size: 13px; }
.empty { padding: var(--s7) var(--s5); text-align: center; display: grid; gap: var(--s3); justify-items: center; }
.empty p { color: var(--muted); }
.button { min-height: 38px; padding: 0 var(--s4); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-2); color: var(--ink); }
.button.primary { background: var(--accent); border-color: var(--accent); color: #171207; font-weight: 600; }

.detail {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(560px, 94vw); z-index: 10;
  background: var(--surface); border-left: 1px solid var(--border); padding: var(--s5);
  overflow-y: auto; margin: 0 0 0 auto; max-height: 100%;
}
.detail[hidden] { display: none; }
.detail::backdrop { background: rgba(5, 8, 6, 0.6); }
.detail-head { display: flex; align-items: start; justify-content: space-between; gap: var(--s4); }
.detail-head > div { min-width: 0; }
.detail-head .sub { overflow-wrap: anywhere; }
.close { flex: none; min-width: 32px; min-height: 32px; padding: 0 var(--s2); white-space: nowrap; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-2); color: var(--ink); }
.detail h2 { margin-top: var(--s1); }
.detail .sub { margin-top: var(--s1); }
.detail-section { margin-top: var(--s5); padding-top: var(--s4); border-top: 1px solid var(--border); }
.detail-section h3 { margin-bottom: var(--s2); }
.equation { display: grid; gap: var(--s2); font-family: var(--font-num); font-size: 13px; }
.equation div { display: flex; justify-content: space-between; gap: var(--s3); }
.equation span { color: var(--muted); }
.equation .total { border-top: 1px solid var(--border); padding-top: var(--s2); }
.equation .total b { color: var(--accent); }
.steps { margin: 0; padding-left: var(--s5); display: grid; gap: var(--s3); }
.steps li { padding-left: var(--s1); }
.steps li::marker { color: var(--accent); font-family: var(--font-num); }
.steps b { display: block; font-weight: 500; }
.cost { color: var(--muted); font-size: 12px; font-family: var(--font-num); }
.peers table { font-size: 13px; }
.peers td, .peers th { padding: var(--s2) var(--s3); }
.risks { margin: 0; padding-left: var(--s4); display: grid; gap: var(--s1); color: var(--muted); font-size: 13px; }
.risks li::marker { color: var(--bad); }
.note { color: var(--muted); font-size: 13px; margin-top: var(--s2); }

.foot { margin-top: var(--s4); padding: var(--s4) var(--s5); display: flex; flex-wrap: wrap; gap: var(--s2) var(--s5); justify-content: space-between; color: var(--faint); font-size: 12px; }
.foot b { color: var(--muted); font-weight: 550; }

@media (max-width: 900px) {
  .shell { padding: var(--s4); }
  .lede { grid-template-columns: 1fr; gap: var(--s4); }
  .facts { border-left: 0; border-top: 1px solid var(--border); padding-left: 0; padding-top: var(--s4); }
  .field input { min-width: 0; width: 100%; }
  .bar { width: 70px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; }
}
